def migrate_cellar_dishes_to_wines(apps, schema_editor):
    Category = apps.get_model('menu', 'Category')
    Dish = apps.get_model('menu', 'Dish')
    Wine = apps.get_model('menu', 'Wine')

    cellar_categories = Category.objects.filter(slug='bodega-mediterranea')
    for category in cellar_categories:
        for dish in Dish.objects.filter(category=category):
            meta = KNOWN_WINE_METADATA.get(dish.name, {})
            parts = [p.strip() for p in (dish.detail or '').split('·') if p.strip()]
            inferred_region = parts[0] if parts else 'Selección Mediterránea'
            inferred_unit = parts[1] if len(parts) > 1 else (dish.price_unit or 'Botella')

            wine, _ = Wine.objects.update_or_create(
                name=dish.name,
                defaults={
                    'wine_type': meta.get('wine_type', 'blanco'),
                    'wine_region': meta.get('wine_region', inferred_region),
                    'varietal': meta.get('varietal', dish.name.split('«')[0].strip() or 'Coupage mediterráneo'),
                    'description': meta.get('description', dish.description),
                    'tasting_notes': meta.get('tasting_notes', dish.description),
                    'price': dish.price,
                    'price_unit': meta.get('price_unit', inferred_unit),
                    'image': dish.image.name if dish.image else '',
                    'is_signature': dish.is_signature,
                    'is_active': dish.is_active,
                    'order': dish.order,
                },
            )
            wine.allergens.set(dish.allergens.all())
            dish.delete()
        category.delete()


